<script setup>
import { onBeforeUnmount, onMounted, ref } from 'vue'; import { api } from '../api'; import { ImageUp, ScanLine, ShieldCheck } from 'lucide-vue-next'; import { emitMotion } from '../motion'
const file=ref(null),preview=ref(''),result=ref(null),capability=ref(null),busy=ref(false),error=ref('')
onMounted(async()=>{capability.value=await api.capabilities().catch(()=>null)});onBeforeUnmount(()=>{if(preview.value)URL.revokeObjectURL(preview.value)})
function choose(event){const selected=event.target.files?.[0];if(!selected)return;if(preview.value)URL.revokeObjectURL(preview.value);file.value=selected;preview.value=URL.createObjectURL(selected);result.value=null;error.value='';emitMotion('focus',{label:selected.type||'image'})}
async function identify(){if(!file.value)return;busy.value=true;error.value='';emitMotion('agent',{label:'vision'});try{result.value=await api.vision(file.value);emitMotion('complete',{label:'vision'})}catch(e){error.value=e.message;emitMotion('error',{label:'vision'})}finally{busy.value=false}}
</script>
<template><div class="page"><header class="page-head"><div><h1>拍照识方</h1><p>从杯型、颜色、装饰和质地给出候选，不把照片猜测当成确定配方。</p></div><span class="chip" :class="capability?.vision?.available?'green':'amber'"><ScanLine :size="14"/>{{capability?.vision?.available?'视觉模型可用':'视觉能力未配置'}}</span></header>
<div class="vision-grid"><section class="panel panel-pad upload"><label class="drop" :class="{filled:preview}"><input type="file" accept="image/jpeg,image/png,image/webp" @change="choose"/><img v-if="preview" :src="preview" alt="待识别鸡尾酒照片"/><span v-else><ImageUp :size="38"/><strong>选择鸡尾酒成品照片</strong><small>JPEG / PNG / WebP，最大 8MB</small></span></label><button class="btn primary" :disabled="!file||busy||!capability?.vision?.available" @click="identify">{{busy?'正在观察':'识别候选配方'}}</button><p class="privacy"><ShieldCheck :size="15"/>图片仅在本次请求内存中处理，请求结束即释放，不会写入磁盘。</p><div v-if="error" class="error-box">{{error}}</div></section>
<section class="panel panel-pad results"><div v-if="!result" class="state"><div><ScanLine :size="36"/><strong>{{capability?.vision?.available?'等待照片':'视觉服务当前不可用'}}</strong>{{capability?.vision?.available?'上传后会列出最多三个候选及判断依据。':'仍可使用配方搜索、酒柜匹配与其他确定性功能。'}}</div></div><template v-else><h2 class="section-title">可见特征</h2><div class="toolbar"><span class="chip" v-for="item in result.observations" :key="item">{{item}}</span></div><h2 class="section-title candidates-title">候选配方</h2><article v-for="item in result.candidates" :key="item.name" class="candidate"><img v-if="item.recipe?.image" :src="item.recipe.image" :alt="item.name"/><div><span class="chip" :class="item.confidence==='high'?'green':'amber'">{{item.confidence==='high'?'较高可信':item.confidence==='medium'?'中等可信':'较低可信'}}</span><h3>{{item.recipe?.name_cn||item.name}}</h3><p>{{item.reason}}</p><router-link v-if="item.recipe" :to="`/recipes/${item.recipe.id}`">查看标准配方</router-link></div></article><p class="safety">{{result.disclaimer}}</p></template></section></div></div></template>
<style scoped>.vision-grid{display:grid;grid-template-columns:minmax(320px,.8fr) minmax(0,1.2fr);gap:18px}.upload{display:grid;gap:14px;align-content:start}.drop{display:grid;place-items:center;min-height:360px;border:1px dashed #aeb6b1;border-radius:7px;background:#f1f2ef;overflow:hidden;cursor:pointer}.drop input{display:none}.drop>span{text-align:center;color:var(--muted)}.drop strong,.drop small{display:block}.drop strong{color:var(--ink);margin:12px 0 5px}.drop img{width:100%;height:100%;max-height:480px;object-fit:contain}.privacy{display:flex;gap:7px;align-items:flex-start;color:var(--muted);font-size:11px}.results{min-height:500px}.candidates-title{margin-top:25px}.candidate{display:grid;grid-template-columns:105px 1fr;gap:13px;border-top:1px solid var(--line);padding:13px 0}.candidate img{width:105px;height:105px;object-fit:cover;border-radius:6px}.candidate h3{margin:7px 0 3px}.candidate p{font-size:12px;color:var(--muted);line-height:1.5}.candidate a{font-size:12px;color:var(--green);font-weight:700}@media(max-width:850px){.vision-grid{grid-template-columns:1fr}.drop{min-height:280px}}</style>
